package main

import (
	"fmt"
	"strings"

	"github.com/ethosagent/meterwise/internal/access"
)

const taxonomyBanner = "// @generated by cmd/gen from internal/access/taxonomy.go. DO NOT EDIT; run `go run ./cmd/gen`.\n"

const taxonomyPath = "web/src/access/taxonomy.ts"

// maxLine is biome's lineWidth for web/: the generated file must already be formatted the way
// the formatter would leave it, because web/biome.json only ignores contract/generated.ts.
const maxLine = 100

// tsStringArray renders ["a", "b"] on one line when it fits in maxLine after prefix and suffix,
// otherwise one element per line with a trailing comma (what biome produces).
func tsStringArray(indent, prefix string, vals []string, suffix string) string {
	quoted := make([]string, len(vals))
	for i, v := range vals {
		quoted[i] = fmt.Sprintf("%q", v)
	}
	one := indent + prefix + "[" + strings.Join(quoted, ", ") + "]" + suffix
	if len(one) <= maxLine {
		return one + "\n"
	}
	var b strings.Builder
	b.WriteString(indent + prefix + "[\n")
	for _, q := range quoted {
		b.WriteString(indent + "  " + q + ",\n")
	}
	b.WriteString(indent + "]" + suffix + "\n")
	return b.String()
}

// genTaxonomyTS renders the TypeScript twin of the RBAC taxonomy.
func genTaxonomyTS() ([]byte, error) {
	var b strings.Builder
	b.WriteString(taxonomyBanner)
	b.WriteString("\nexport type Scope = \"workspace\" | \"org\";\n\n")
	b.WriteString("export interface ResourceSpec {\n  scope: Scope;\n  actions: readonly string[];\n}\n\n")
	b.WriteString("export const TAXONOMY = {\n")
	var perms []string
	for _, r := range access.Taxonomy() {
		b.WriteString(tsStringArray("  ", fmt.Sprintf("%s: { scope: %q, actions: ", r.Type, string(r.Scope)), r.Actions, " },"))
		for _, a := range r.Actions {
			perms = append(perms, r.Type+":"+a)
		}
	}
	b.WriteString("} as const satisfies Record<string, ResourceSpec>;\n\n")
	b.WriteString("export type ResourceType = keyof typeof TAXONOMY;\n\n")
	b.WriteString(tsStringArray("", "export const PERMISSIONS = ", perms, " as const;"))
	b.WriteString("\nexport type PermissionName = (typeof PERMISSIONS)[number];\n")
	return []byte(b.String()), nil
}
